[application]
config/use_custom_user_dir=true
config/custom_user_dir_name="OpenRTSPolishMacFinal-20261024-b"

run/main_loop_type="ReleaseBenchmark"
run/main_scene="res://BenchmarkBootstrap.tscn"
run/flush_stdout_on_print=true

config/name="Open RTS"
config/version="0.16.2"
